const path = require('path');
const { chromium } = require(path.join('/home/user/Web-Calculator-fresh/sabee-khan-calculator/node_modules/playwright'));
const OUT = __dirname;
const URL = 'http://localhost:4174/';
const widths = [320, 375, 768, 1280];
const themes = ['light', 'dark'];
const scenarios = {
  idle: { earned: '', total: '', pass: '70' },
  result: { earned: '17.5', total: '23', pass: '70' },
  error: { earned: '23.5', total: '23', pass: '70' },
  twoerrors: { earned: 'abc', total: '0', pass: '70' },
  threeerrors: { earned: 'abc', total: '-5', pass: '100.1' },
  longest: { earned: '10', total: '1000000.01', pass: '70' },
};

function lum(rgb) {
  const m = rgb.match(/[\d.]+/g).slice(0, 3).map(Number).map(v => { v /= 255; return v <= 0.03928 ? v / 12.92 : Math.pow((v + 0.055) / 1.055, 2.4); });
  return 0.2126 * m[0] + 0.7152 * m[1] + 0.0722 * m[2];
}
function cr(a, b) { const x = lum(a), y = lum(b); return ((Math.max(x, y) + 0.05) / (Math.min(x, y) + 0.05)).toFixed(2); }

async function setVals(page, v) {
  for (const [id, val] of [['#earned', v.earned], ['#total', v.total], ['#pass-mark', v.pass]]) {
    await page.fill(id, val);
  }
  await page.waitForTimeout(50);
}

async function measure(page) {
  return page.evaluate(() => {
    const card = document.querySelector('.card').getBoundingClientRect();
    const btn = document.querySelector('.btn').getBoundingClientRect();
    const fields = ['earned', 'total', 'pass-mark'].map(id => {
      const inp = document.getElementById(id);
      const slot = document.getElementById(id + '-error');
      const cs = getComputedStyle(slot);
      const ics = getComputedStyle(inp);
      const r = slot.getBoundingClientRect();
      const txt = slot.textContent.trim();
      const span = [...slot.childNodes].find(n => n.nodeType === 1 && n.tagName !== 'svg' && n.tagName !== 'SVG') || slot;
      const range = document.createRange(); range.selectNodeContents(slot);
      const rects = [...range.getClientRects()];
      const textBottom = rects.length ? Math.max(...rects.map(x => x.bottom)) : r.top;
      return {
        id, text: txt, invalid: inp.getAttribute('aria-invalid'), describedby: inp.getAttribute('aria-describedby'),
        hasIcon: !!slot.querySelector('svg'), iconHidden: slot.querySelector('svg')?.getAttribute('aria-hidden'),
        slotH: r.height, minH: cs.minHeight, overflow: textBottom - r.bottom, slotRight: r.right,
        color: cs.color, inputBorder: ics.borderTopColor, inputShadow: ics.boxShadow, inputH: inp.getBoundingClientRect().height,
        inputTop: inp.getBoundingClientRect().top,
      };
    });
    const rb = document.querySelector('.result-body');
    const rm = rb.querySelector('.result-msg');
    return {
      cardH: card.height, cardTop: card.top, btnTop: btn.top, scrollW: document.documentElement.scrollWidth,
      fields,
      result: { text: rb.textContent.trim(), hasIcon: !!rb.querySelector('.result-msg svg'), color: rm ? getComputedStyle(rm).color : null, h: rb.getBoundingClientRect().height },
      surface: getComputedStyle(document.querySelector('.card')).backgroundColor,
      status: document.querySelector('[role="status"]')?.textContent,
    };
  });
}

(async () => {
  const browser = await chromium.launch();
  const report = [];
  for (const theme of themes) for (const w of widths) {
    const ctx = await browser.newContext({ viewport: { width: w, height: 1000 }, colorScheme: theme, deviceScaleFactor: 2 });
    const page = await ctx.newPage();
    const logs = [];
    page.on('console', m => logs.push(m.type() + ': ' + m.text()));
    page.on('pageerror', e => logs.push('pageerror: ' + e.message));
    await page.goto(URL);
    for (const [name, v] of Object.entries(scenarios)) {
      await setVals(page, v);
      await page.mouse.click(1, 1);
      const m = await measure(page);
      m.fields.forEach(f => { f.contrast = cr(f.color, m.surface); });
      if (m.result.color) m.result.contrast = cr(m.result.color, m.surface);
      report.push({ theme, w, name, ...m });
      await page.screenshot({ path: path.join(OUT, `s3-${name}-${w}-${theme}.png`), fullPage: true });
    }
    // recovery: from single error, fix marks earned
    await setVals(page, scenarios.error);
    await page.fill('#earned', '20');
    await page.waitForTimeout(50);
    await page.mouse.click(1, 1);
    const rec = await measure(page);
    report.push({ theme, w, name: 'recovery', ...rec });
    await page.screenshot({ path: path.join(OUT, `s3-recovery-${w}-${theme}.png`), fullPage: true });
    // focus ring on a field in error (keyboard)
    await setVals(page, scenarios.error);
    await page.mouse.click(1, 1);
    await page.keyboard.press('Tab'); // first tabbable = earned
    const foc = await page.evaluate(() => { const a = document.activeElement; const cs = getComputedStyle(a); return { id: a.id, outline: cs.outlineStyle + ' ' + cs.outlineWidth + ' ' + cs.outlineColor, offset: cs.outlineOffset, border: cs.borderTopColor, invalid: a.getAttribute('aria-invalid') }; });
    report.push({ theme, w, name: 'focus-in-error', focus: foc });
    const box = await page.locator('#earned').boundingBox();
    await page.screenshot({ path: path.join(OUT, `s3-focuserror-${w}-${theme}.png`), clip: { x: Math.max(0, box.x - 24), y: box.y - 40, width: Math.min(w - Math.max(0, box.x - 24), box.width + 48), height: box.height + 100 } });
    report.push({ theme, w, name: 'console', logs });
    await ctx.close();
  }
  await browser.close();
  require('fs').writeFileSync(path.join(OUT, 'report.json'), JSON.stringify(report, null, 1));
  console.log('done', report.length);
})();

